questions.schema_sql:
CREATE TABLE accounts (id INTEGER PRIMARY KEY, owner TEXT, branch TEXT, balance INTEGER, opened TEXT);
CREATE TABLE transactions (id INTEGER PRIMARY KEY, account_id INTEGER, amount INTEGER, at TEXT);
CREATE INDEX accounts_owner ON accounts(owner);
CREATE INDEX accounts_branch ON accounts(branch);
CREATE INDEX accounts_balance ON accounts(balance);
CREATE INDEX transactions_account ON transactions(account_id);
CREATE INDEX transactions_at ON transactions(at);

